import{PostMessageApiServer}from"chrome://resources/ash/common/post_message_api/post_message_api_server.js";import{AddSupervisionHandler}from"./add_supervision.mojom-webui.js";import{isLocalHostForTesting}from"./add_supervision_ui.js";export class AddSupervisionApiServer extends PostMessageApiServer{constructor(ui,webviewElement,targetURL,originURLPrefix){super(webviewElement,targetURL,originURLPrefix);this.ui=ui;this.addSupervisionHandler=AddSupervisionHandler.getRemote();this.registerMethod("logOut",this.logOut.bind(this));this.registerMethod("getInstalledArcApps",this.getInstalledArcApps.bind(this));this.registerMethod("requestClose",this.requestClose.bind(this));this.registerMethod("notifySupervisionEnabled",this.notifySupervisionEnabled.bind(this));this.registerMethod("setCloseOnEscape",this.setCloseOnEscape.bind(this))}initialize(){if(isLocalHostForTesting(this.targetUrl())){return}super.initialize()}onInitializationError(){this.ui.showErrorPage()}logOut(){return this.addSupervisionHandler.logOut()}getInstalledArcApps(){return this.addSupervisionHandler.getInstalledArcApps()}requestClose(){return this.addSupervisionHandler.requestClose()}notifySupervisionEnabled(){return this.addSupervisionHandler.notifySupervisionEnabled()}setCloseOnEscape(params){const enabled=params[0];return this.addSupervisionHandler.setCloseOnEscape(enabled)}}